    """Return the length of the longest strictly increasing subsequence.
    Uses classic O(n^2) dynamic programming which is simple and reliable.
    """
    if not nums:
        return 0
    n = len(nums)
    dp = [1] * n  # dp[i] = length of LIS ending at i
    for i in range(1, n):
        best = 1
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > best:
