    # Ensure the input is a string; otherwise return empty list.
    if not isinstance(s, str):
        return []
    if not s:
        return []
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

