def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Uses integer arithmetic to avoid float precision issues.
    """
    stack = []
    for token in tokens:
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Handle division by zero explicitly if it ever occurs
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Compute truncation toward zero using absolute values
                sign = -1 if (a < 0) ^ (b < 0) else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

