def solve(nums):
    """
    Return the length of the longest strictly increasing subsequence in the list `nums`.
    If `nums` is not a list (or is empty), return 0.
    """
    # Guard against incorrect input types.
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0

    import bisect
    tails = []  # tails[i] = minimal possible tail of an inc. subseq of length i+1
    for x in nums:
        # Skip non‑numeric entries; they cannot be part of a strictly increasing subsequence.
        try:
            # Ensure comparison works; if x is not comparable, ignore it.
            _ = x < x
        except Exception:
            continue
        # Find the first index in tails where tails[idx] >= x.
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

