def solve(nums):
    """
    Return the length of the longest strictly increasing subsequence in `nums`.
    """
    if not nums:
        return 0

    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # Find the first index in tails with a value >= x.
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

