def solve(grid):
    # Defensive handling for non-rectangular grids or empty rows
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def get_neighbors(r, c):
        for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr, nc
    def dfs(r, c):
        stack = [(r, c)]
        visited.add((r, c))
        while stack:
            x, y = stack.pop()
            for nx, ny in get_neighbors(x, y):
                if (nx, ny) not in visited and grid[nx][ny] == 1:
                    visited.add((nx, ny))
                    stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

