{"task_id": "T32", "code": "def solve(s: str) -> int:
    """Convert a Roman numeral to an integer.

    The input may contain leading/trailing whitespace and be in any case.
    An empty string yields 0.
    """
    if not s:
        return 0
    s = s.strip().upper()
    if not s:
        return 0
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    n = len(s)
    while i < n:
        if i + 1 < n and values[s[i]] < values[s[i + 1]]:
            total += values[s[i + 1]] - values[s[i]]
            i += 2
        else:
            total += values[s[i]]
            i += 1
    return total"}

