def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Handles non‑list inputs and non‑numeric elements gracefully.
    """
    if not isinstance(nums, (list, tuple)):
        return 0
    if not nums:
        return 0
    import bisect
    tails = []
    for x in nums:
        # Ensure x is comparable (int or float)
        try:
            _ = x < x
        except Exception:
            continue
        # Find position to replace in tails (first >= x)
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

