def solve(a, b):
    # Ensure a is the shorter string to use less space
    if len(a) > len(b):
        a, b = b, a
    n, m = len(a), len(b)
    prev = list(range(n+1))  # distance for a prefix vs empty b
    for j in range(1, m+1):
        cur = [j] + [0]*n
        for i in range(1, n+1):
            if a[i-1] == b[j-1]:
                cur[i] = prev[i-1]
            else:
                cur[i] = 1 + min(prev[i],      # delete from a (i stays, j-1)
                                   cur[i-1],    # insert into a (i-1, j)
                                   prev[i-1])   # replace
        prev = cur
    return prev[n]

