def solve(s):
    """Run‑length encode the input sequence.
    Accepts any iterable (including strings). Returns a list of [element, count] pairs.
    Returns [] for non‑iterable inputs or empty input.
    """
    try:
        seq = list(s)
    except Exception:
        return []
    if not seq:
        return []
    res = []
    cur = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

