def solve(s):
    # Handle bytes and bytearray by decoding to string
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            return []
    # Try to treat s as an iterable of characters
    try:
        seq = list(s)
    except TypeError:
        return []
    if not seq:
        return []
    res = []
    cur = seq[0]
    cnt = 1
    for ch in seq[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

